package com.codearena.submission;
import com.codearena.common.api.ApiResponse; import com.codearena.common.domain.*; import com.codearena.problem.*; import jakarta.validation.constraints.*; import java.util.*; import org.springframework.amqp.rabbit.core.RabbitTemplate; import org.springframework.http.*; import org.springframework.lang.NonNull; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException;
@RestController @RequestMapping("/api/v1/submissions") public class SubmissionController { final SubmissionRepository repo;final ProblemRepository problems;final RabbitTemplate rabbit; SubmissionController(SubmissionRepository r,ProblemRepository p,RabbitTemplate q){repo=r;problems=p;rabbit=q;} record Create(@NotNull @NonNull UUID problemId,UUID contestId,@NotBlank @Size(max=32) String language,@NotBlank @Size(max=262144) String sourceCode){} @PostMapping @ResponseStatus(HttpStatus.ACCEPTED) ApiResponse<Submission> create(@AuthenticationPrincipal String userId,@RequestBody @jakarta.validation.Valid Create c){var p=problems.findById(c.problemId).filter(x->x.published).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Problem unavailable"));if(!p.supportedLanguages.contains(c.language))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Unsupported language");var s=new Submission();s.studentId=UUID.fromString(userId);s.problemId=c.problemId;s.contestId=c.contestId;s.language=c.language;s.sourceCode=c.sourceCode;s.status=SubmissionStatus.QUEUED;repo.save(s);rabbit.convertAndSend("submission.exchange","submission.created",new SubmissionJob(s.id));return ApiResponse.of(s);} @GetMapping ApiResponse<List<Submission>> mine(@AuthenticationPrincipal String id){return ApiResponse.of(repo.findByStudentIdOrderByCreatedAtDesc(UUID.fromString(id)));} @GetMapping("/{id}") ApiResponse<Submission> get(@AuthenticationPrincipal String uid,@PathVariable @NonNull UUID id){var s=repo.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));if(!s.studentId.equals(UUID.fromString(uid)))throw new ResponseStatusException(HttpStatus.FORBIDDEN);return ApiResponse.of(s);} public record SubmissionJob(UUID submissionId){} }
